Future<void> handleIncomingCall(Map<String, dynamic> payload) async {
  if (state != null) {
    // Already in a call — tell the caller we're busy.
    ref.read(signalingServiceProvider).emitCallBusy(
          callId: payload['call_id'] as String? ?? '',
          to: payload['from'] as String? ?? '',
        );
    return;
