  @override
  String? build() => null;
  void set(String path) => state = path;
  String? consume() {
    final v = state;
    state = null;
    return v;
  }
}

final pendingDeepLinkProvider =
    NotifierProvider<_PendingDeepLinkNotifier, String?>(
        _PendingDeepLinkNotifier.new);

