// forwards it to the original listener chain. Nginx (prompt 10) routes the external
// path /signal/health → /health on this container.

const httpServer = http.createServer((req, res) => {
  if (req.method === 'GET' && req.url === '/health') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'ok' }));
  }
  // All other paths are handled by engine.io (added after createServer).
});

// ── Socket.IO ─────────────────────────────────────────────────────────────────

const io = new Server(httpServer, {
  cors: { origin: false },       // mobile clients only — no browser CORS needed
  transports: ['websocket'],
  pingTimeout: 60_000,
  pingInterval: 25_000,
  upgradeTimeout: 10_000,
  path: '/signal',
});

// Auth middleware — runs before every connection
io.use((socket, next) => {
  const token = socket.handshake.auth.token;
  if (!token) return next(new Error('No token'));
  try {
    const { userId } = verifyToken(token);
    socket.userId = userId;
    next();
  } catch (err) {
    logger.warn({ event: 'auth_rejected', error: err.message });
    next(new Error('Authentication failed'));
  }
});

import re

from pydantic import BaseModel, field_validator


class RegisterRequest(BaseModel):
    name: str
    phone: str
    password: str

    @field_validator("phone")
    @classmethod
    def validate_phone(cls, v: str) -> str:
        if not re.match(r"^\+[1-9]\d{7,14}$", v):
            raise ValueError("Phone must be E.164 format, e.g. [REDACTED_PHONE_US]")
        return v

    @field_validator("password")
    @classmethod
    def validate_password(cls, v: str) -> str:
        if len(v) < 8:
            raise ValueError("Password must be at least 8 characters")
        return v


class RegisterResponse(BaseModel):
    otp_sent: bool
    # Only populated when DEBUG=true — never expose OTPs in production
    debug_otp: str | None = None


class VerifyOtpRequest(BaseModel):
    phone: str
    otp: str


class LoginRequest(BaseModel):
    phone: str
    password: str
    device_id: str
    fcm_token: str | None = None


class TokenResponse(BaseModel):
    access_token: str
    refresh_token: str
    token_type: str = "bearer"
    expires_in: int  # seconds


class RefreshRequest(BaseModel):
    refresh_token: str
    device_id: str


class LogoutRequest(BaseModel):
    refresh_token: str

