            key: _formKey,
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  'Set your profile',
                  style: TextStyle(
                    fontSize: 30,
                    fontWeight: FontWeight.w600,
                    color: fg1,
                    height: 1.15,
                    letterSpacing: -0.01,
                  ),
                ),
                const SizedBox(height: 10),
                Text(
                  'Pick the name family sees. We\'ll send a code to your phone to verify.',
                  style: TextStyle(fontSize: 16, color: fg2, height: 1.4),
                ),
                const SizedBox(height: 32),
                Focus(
                  onFocusChange: (f) {
                    if (!f) setState(() => _touched.add('name'));
                  },
                  child: FlTextField(
                    label: 'Display name',
                    controller: _nameCtrl,
                    textInputAction: TextInputAction.next,
                    validator: _touched.contains('name') ? _validateName : null,
                  ),
                ),
                const SizedBox(height: 14),
                Focus(
                  onFocusChange: (f) {
                    if (!f) setState(() => _touched.add('phone'));
                  },
                  child: FlTextField(
                    label: 'Phone number',
                    controller: _phoneCtrl,
                    hint: '(555) 000-0000',
                    keyboardType: TextInputType.phone,
                    textInputAction: TextInputAction.done,
                    prefixWidget: const PhonePrefix(),
                    inputFormatters: [
                      FilteringTextInputFormatter.digitsOnly,
                      LengthLimitingTextInputFormatter(10),
                    ],
                    onFieldSubmitted: (_) => _submit(),
                    validator:
                        _touched.contains('phone') ? _validatePhone : null,
                  ),
                ),
                const SizedBox(height: 32),
                FlButton(
                  label: 'Send code',
                  loadingLabel: 'Sending…',
                  onPressed: _isLoading ? null : _submit,
                  isLoading: _isLoading,
                ),
                const SizedBox(height: 20),
                Text(
                  'By continuing, you agree to our Terms and Privacy notice.',
                  textAlign: TextAlign.center,
                  style: TextStyle(fontSize: 13, color: fg3, height: 1.45),
                ),
                if (AppConfig.uiOnly) ...[
                  const SizedBox(height: 12),
                  Center(
                    child: TextButton(
                      onPressed: _isLoading
                          ? null
                          : () => ref
                              .read(authNotifierProvider.notifier)
                              .signInDemo(),
                      child: const Text(
                        'Explore app without signing in',
                        style: TextStyle(
                          color: AppColors.primary,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                    ),
                  ),
                ],
                const SizedBox(height: 24),
                Center(
                  child: GestureDetector(
                    onTap: () => context.go('/login'),
                    child: const Text(
                      '← Back to login',
                      style: TextStyle(
                        fontSize: 15,
                        color: AppColors.primary,
                        fontWeight: FontWeight.w500,
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

