1	import 'dart:async';
2	import 'package:dio/dio.dart';
3	
4	/// Attaches Bearer tokens to every outgoing request and handles 401 responses
5	/// by attempting a single token refresh. Concurrent 401s are serialized so
6	/// only one refresh call is made.
7	class TokenInterceptor extends Interceptor {
8	  final String? Function() getAccessToken;
9	
10	  /// Returns true if the refresh succeeded and the new tokens have been saved.
11	  final Future<bool> Function() refreshTokens;
12	
13	  /// Called when a refresh fails — should clear auth state and navigate to login.
14	  final void Function() onAuthExpired;
15	
16	  // Non-null while a refresh is in flight; concurrent 401 waiters await this.
17	  Completer<bool>? _refreshCompleter;
18	
19	  TokenInterceptor({
20	    required this.getAccessToken,
21	    required this.refreshTokens,
22	    required this.onAuthExpired,
23	  });
24	
25	  @override
26	  void onRequest(
27	    RequestOptions options,
28	    RequestInterceptorHandler handler,
29	  ) {
30	    final token = getAccessToken();
31	    if (token != null) {
32	      options.headers['Authorization'] = 'Bearer $token';
33	    }
34	    handler.next(options);
35	  }
36	
37	  @override
38	  Future<void> onError(
39	    DioException err,
40	    ErrorInterceptorHandler handler,
41	  ) async {
42	    if (err.response?.statusCode != 401) {
43	      handler.next(err);
44	      return;
45	    }
46	
47	    // Avoid infinite loop if the refresh endpoint itself returns 401.
48	    if (err.requestOptions.path.contains('/api/auth/refresh')) {
49	      onAuthExpired();
50	      handler.next(err);
51	      return;
52	    }
53	
54	    // Prevent double-retry on requests that were already replayed once.
55	    if (err.requestOptions.headers.containsKey('_retry')) {
56	      onAuthExpired();
57	      handler.next(err);
58	      return;
59	    }
60	
61	    if (_refreshCompleter != null) {
62	      // Wait for the in-flight refresh to finish, then replay.
63	      final success = await _refreshCompleter!.future;
64	      if (success) {
65	        handler.resolve(await _replay(err.requestOptions));
66	      } else {
67	        handler.next(err);
68	      }
69	      return;
70	    }
71	
72	    _refreshCompleter = Completer<bool>();
73	    bool success = false;
74	    try {
75	      success = await refreshTokens();
76	      _refreshCompleter!.complete(success);
77	    } catch (_) {
78	      _refreshCompleter!.complete(false);
79	    } finally {
80	      _refreshCompleter = null;
81	    }
82	
83	    if (success) {
84	      handler.resolve(await _replay(err.requestOptions));
85	    } else {
86	      onAuthExpired();
87	      handler.next(err);
88	    }
89	  }
90	
91	  Future<Response<dynamic>> _replay(RequestOptions original) {
92	    // Use a fresh Dio instance scoped to the base URL to replay the request.
93	    // The interceptor sets a fresh token in onRequest on the replayed call.
94	    final dio = Dio(BaseOptions(baseUrl: original.baseUrl));
95	    dio.interceptors.add(
96	      InterceptorsWrapper(
97	        onRequest: (opts, handler) {
98	          final token = getAccessToken();
99	          if (token != null) opts.headers['Authorization'] = 'Bearer $token';
100	          opts.headers['_retry'] = 'true';
101	          handler.next(opts);
102	        },
103	      ),
104	    );
105	    return dio.request(
106	      original.path,
107	      data: original.data,
108	      queryParameters: original.queryParameters,
109	      options: Options(
110	        method: original.method,
111	        headers: original.headers,
112	        responseType: original.responseType,
113	        contentType: original.contentType,
114	      ),
115	    );
116	  }
117	}
